UPDATE pet_order SET appointment_start_at=#{newStart},appointment_end_at=#{newEnd},reschedule_count=1,
 order_stage='PENDING_CONFIRM',confirm_mode=NULL,confirmed_at=NULL,confirm_deadline=#{newConfirmDeadline},version=version+1,updated_at=#{rescheduledAt}
WHERE id=#{orderId} AND version=#{oldOrderVersion} AND reschedule_count=0 AND order_stage IN ('PENDING_CONFIRM','PENDING_SERVICE')
 AND payment_status='PAID' AND verification_status='UNVERIFIED' AND refund_order_id IS NULL
 AND current_refund_application_id IS NULL AND current_aftersale_id IS NULL AND canceled_at IS NULL AND cancel_reason IS NULL AND refunded_amount=0
 AND appointment_start_at > #{rescheduledAt}
